#!/usr/bin/env python3
"""
Apply the follow-up change for rainwater automation:
- keep the existing option/config wiring
- replace building sleep/wake with per-recipe active toggling
- update user-facing labels/descriptions from auto-pause to recipe auto-disable/auto-enable

Run from the ATS-StockAlert repository root after the rainwater-auto-pause patch has been applied:
    python apply_rainwater_recipe_toggle.py
"""
from pathlib import Path
import sys

ROOT = Path.cwd()

RAINWATER_AUTO_PAUSE = 'using System.Collections.Generic;\nusing System.Linq;\nusing Eremite.Buildings;\nusing Eremite.Model;\nusing StockAlert.Config;\nusing StockAlert.Infrastructure.Plugin;\nusing UnityEngine;\n\nnamespace StockAlert.Game\n{\n    /// <summary>\n    /// Automatically disables enabled recipes in buildings whose Rain Engines are switched on\n    /// when the rainwater type they consume is fully depleted, and optionally re-enables\n    /// only those recipes once that rainwater is available again.\n    ///\n    /// This intentionally does not sleep/pause the building. Disabling the recipe state\n    /// prevents new production cycles from being started, while allowing the currently\n    /// running production cycle to finish normally.\n    ///\n    /// Only recipes disabled by this feature are ever re-enabled by it. Recipes the player\n    /// had disabled manually are left alone.\n    /// </summary>\n    internal static class RainwaterAutoPause\n    {\n        // Building id -> recipe keys disabled by this feature.\n        private static readonly Dictionary<int, HashSet<string>> DisabledRecipesByBuilding =\n            new Dictionary<int, HashSet<string>>();\n\n        // Avoids resume/disable flapping when only a trickle of water arrives.\n        private const int MaxResumeThreshold = 10;\n\n        public static void Clear()\n        {\n            DisabledRecipesByBuilding.Clear();\n        }\n\n        public static void Process()\n        {\n            if (!ConfigManager.AutoPauseOnNoRainwater)\n            {\n                if (DisabledRecipesByBuilding.Count > 0)\n                {\n                    DisabledRecipesByBuilding.Clear();\n                }\n\n                return;\n            }\n\n            if (!GameAPI.IsGameActive())\n            {\n                return;\n            }\n\n            var workshops = GameAPI.GetWorkshopBuildings();\n            if (workshops.Count == 0)\n            {\n                return;\n            }\n\n            var seenIds = new HashSet<int>();\n            List<string> disabledNames = null;\n            List<string> enabledNames = null;\n\n            foreach (var workshop in workshops)\n            {\n                if (workshop == null)\n                {\n                    continue;\n                }\n\n                seenIds.Add(workshop.Id);\n\n                var buildingState = workshop.BuildingState;\n                var water = workshop.model?.rainpunk?.water;\n                var state = workshop.state;\n\n                if (buildingState == null ||\n                    !buildingState.finished ||\n                    water == null ||\n                    state == null ||\n                    state.recipes == null ||\n                    !state.rainpunkUnlocked)\n                {\n                    DisabledRecipesByBuilding.Remove(workshop.Id);\n                    continue;\n                }\n\n                var waterLeft = GameAPI.GetCityWaterLeft(water);\n                if (waterLeft < 0)\n                {\n                    // Water amount could not be determined - never act on unknown data.\n                    continue;\n                }\n\n                if (DisabledRecipesByBuilding.TryGetValue(workshop.Id, out var disabledRecipeKeys))\n                {\n                    if (ConfigManager.AutoResumeOnRainwater && waterLeft >= GetResumeThreshold(water))\n                    {\n                        if (EnableRecipesDisabledByMod(workshop, disabledRecipeKeys) > 0)\n                        {\n                            enabledNames ??= new List<string>();\n                            enabledNames.Add(GameAPI.GetBuildingDisplayName(workshop.BuildingModel));\n                        }\n\n                        DisabledRecipesByBuilding.Remove(workshop.Id);\n                        continue;\n                    }\n\n                    if (waterLeft <= 0 && HasRunningEngines(state))\n                    {\n                        if (DisableActiveRecipes(workshop, disabledRecipeKeys) > 0)\n                        {\n                            disabledNames ??= new List<string>();\n                            disabledNames.Add(GameAPI.GetBuildingDisplayName(workshop.BuildingModel));\n                        }\n                    }\n\n                    continue;\n                }\n\n                if (buildingState.isSleeping || waterLeft > 0 || !HasRunningEngines(state))\n                {\n                    continue;\n                }\n\n                var newlyDisabledRecipeKeys = new HashSet<string>();\n                if (DisableActiveRecipes(workshop, newlyDisabledRecipeKeys) > 0)\n                {\n                    DisabledRecipesByBuilding[workshop.Id] = newlyDisabledRecipeKeys;\n                    disabledNames ??= new List<string>();\n                    disabledNames.Add(GameAPI.GetBuildingDisplayName(workshop.BuildingModel));\n                }\n            }\n\n            RemoveStaleEntries(seenIds);\n            AnnounceDisabled(disabledNames);\n\n            if (enabledNames != null)\n            {\n                Plugin.Log("Rainwater available again, re-enabled recipes in: " + string.Join(", ", enabledNames.ToArray()));\n            }\n        }\n\n        private static int DisableActiveRecipes(Workshop workshop, HashSet<string> disabledRecipeKeys)\n        {\n            var recipes = workshop?.state?.recipes;\n            if (recipes == null)\n            {\n                return 0;\n            }\n\n            var changed = 0;\n            for (var i = 0; i < recipes.Count; i++)\n            {\n                var recipe = recipes[i];\n                if (recipe == null || !recipe.active)\n                {\n                    continue;\n                }\n\n                recipe.active = false;\n                disabledRecipeKeys.Add(GetRecipeKey(recipe, i));\n                changed++;\n            }\n\n            return changed;\n        }\n\n        private static int EnableRecipesDisabledByMod(Workshop workshop, HashSet<string> disabledRecipeKeys)\n        {\n            var recipes = workshop?.state?.recipes;\n            if (recipes == null || disabledRecipeKeys == null || disabledRecipeKeys.Count == 0)\n            {\n                return 0;\n            }\n\n            var changed = 0;\n            for (var i = 0; i < recipes.Count; i++)\n            {\n                var recipe = recipes[i];\n                if (recipe == null || !disabledRecipeKeys.Contains(GetRecipeKey(recipe, i)))\n                {\n                    continue;\n                }\n\n                if (!recipe.active)\n                {\n                    recipe.active = true;\n                    changed++;\n                }\n            }\n\n            return changed;\n        }\n\n        private static string GetRecipeKey(RecipeState recipe, int index)\n        {\n            if (!string.IsNullOrWhiteSpace(recipe.model))\n            {\n                return recipe.model;\n            }\n\n            if (!string.IsNullOrWhiteSpace(recipe.productName))\n            {\n                return "product:" + recipe.productName;\n            }\n\n            return "index:" + index;\n        }\n\n        private static bool HasRunningEngines(WorkshopState state)\n        {\n            var engines = state?.engines;\n            if (engines == null)\n            {\n                return false;\n            }\n\n            foreach (var engine in engines)\n            {\n                if (engine != null && engine.requestedLevel > 0)\n                {\n                    return true;\n                }\n            }\n\n            return false;\n        }\n\n        private static int GetResumeThreshold(WaterModel water)\n        {\n            var capacity = GameAPI.GetCityWaterCapacity(water);\n            if (capacity <= 0)\n            {\n                return 1;\n            }\n\n            return Mathf.Clamp(capacity / 10, 1, MaxResumeThreshold);\n        }\n\n        private static void RemoveStaleEntries(HashSet<int> seenIds)\n        {\n            if (DisabledRecipesByBuilding.Count == 0)\n            {\n                return;\n            }\n\n            var staleIds = DisabledRecipesByBuilding.Keys.Where(id => !seenIds.Contains(id)).ToArray();\n            foreach (var id in staleIds)\n            {\n                DisabledRecipesByBuilding.Remove(id);\n            }\n        }\n\n        private static void AnnounceDisabled(List<string> disabledNames)\n        {\n            if (disabledNames == null || disabledNames.Count == 0)\n            {\n                return;\n            }\n\n            var names = string.Join(", ", disabledNames.Take(5).ToArray());\n            if (disabledNames.Count > 5)\n            {\n                names += $" and {disabledNames.Count - 5} more";\n            }\n\n            GameAPI.PublishNews(\n                disabledNames.Count == 1\n                    ? "Out of rainwater - disabled recipes in 1 building."\n                    : $"Out of rainwater - disabled recipes in {disabledNames.Count} buildings.",\n                names\n            );\n            Plugin.Log("Rainwater depleted, disabled recipes in: " + names);\n        }\n    }\n}\n'
REPLACEMENTS = {'Config/ConfigManager.cs': [('Automatically pause buildings with running Rain Engines when the rainwater type they use is fully depleted.', 'Automatically disable enabled recipes in buildings with running Rain Engines when the rainwater type they use is fully depleted. Current production cycles are allowed to finish.'), ('Automatically resume buildings paused by the rainwater auto-pause once their rainwater type is available again. Buildings manually resumed by the player are left alone.', 'Automatically re-enable recipes disabled by the rainwater automation once their rainwater type is available again. Recipes disabled manually by the player are left alone.')], 'UI/Panels/UIController.cs': [('Auto-pause buildings when out of rainwater', 'Auto-disable recipes when out of rainwater'), ('Auto-resume when rainwater returns', 'Auto-enable recipes when rainwater returns')], 'README.md': [('It can also optionally auto-pause buildings with running Rain Engines when the rainwater type they use runs out, and auto-resume them once rainwater is available again.', 'It can also optionally disable enabled recipes in buildings with running Rain Engines when the rainwater type they use runs out, and re-enable only those recipes once rainwater is available again.'), ('enable rainwater auto-pause in the `F8` window to pause buildings with running Rain Engines when their rainwater runs out, and resume them when it returns.', 'enable rainwater recipe auto-disable in the `F8` window to disable recipes in buildings with running Rain Engines when their rainwater runs out, and re-enable those recipes when it returns.'), ('enable rainwater recipe auto-disable in the `F8` window to pause buildings with running Rain Engines when their rainwater runs out, and resume them when it returns.', 'enable rainwater recipe auto-disable in the `F8` window to disable recipes in buildings with running Rain Engines when their rainwater runs out, and re-enable those recipes when it returns.'), ('## Rainwater auto-pause option', '## Rainwater recipe auto-disable option'), ('when enabled, the mod watches every building that has Rain Engines installed and switched on (any engine knob set above 0)\n- when the rainwater type that building uses (Drizzle, Clearance, or Storm Water) is fully depleted city-wide, the building is paused, exactly as if you had clicked its in-game pause button\n- a news alert lists the buildings that were paused\n- by default, buildings paused this way are automatically resumed once their rainwater type is available again (a small buffer of roughly 10% of tank capacity, up to 10 water, is required before resuming to avoid rapid pause/resume cycles); this auto-resume can be disabled separately\n- only buildings paused by the mod are ever resumed by it - if you resume a paused building manually, the mod stops managing it until it pauses it again; buildings you paused yourself are never touched\n- buildings without Rain Engines installed, with all engines set to 0, or with rainpunk not yet unlocked are ignored\n- disabling the option stops further automatic changes, but does not resume buildings that are already paused', "when enabled, the mod watches every building that has Rain Engines installed and switched on (any engine knob set above 0)\n- when the rainwater type that building uses (Drizzle, Clearance, or Storm Water) is fully depleted city-wide, the mod disables the building's currently enabled recipes instead of sleeping/pausing the building\n- current production cycles are left alone; disabling the recipe only prevents new cycles from being started\n- a news alert lists the buildings whose recipes were disabled\n- by default, recipes disabled this way are automatically re-enabled once their rainwater type is available again (a small buffer of roughly 10% of tank capacity, up to 10 water, is required before re-enabling to avoid rapid disable/enable cycles); this auto-enable can be disabled separately\n- only recipes disabled by the mod are ever re-enabled by it; recipes disabled manually by the player are never touched\n- buildings without Rain Engines installed, with all engines set to 0, or with rainpunk not yet unlocked are ignored\n- disabling the option stops further automatic changes, but does not re-enable recipes that are already disabled"), ('rainwater auto-pause', 'rainwater recipe auto-disable')]}

try:
    target = ROOT / "Game/RainwaterAutoPause.cs"
    if not target.exists():
        raise RuntimeError("Game/RainwaterAutoPause.cs not found. Apply the rainwater auto-pause patch first.")
    target.write_text(RAINWATER_AUTO_PAUSE, encoding="utf-8")

    changed = ["Game/RainwaterAutoPause.cs"]
    for rel_path, pairs in REPLACEMENTS.items():
        path = ROOT / rel_path
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8")
        original = text
        for old, new in pairs:
            text = text.replace(old, new)
        if text != original:
            path.write_text(text, encoding="utf-8")
            changed.append(rel_path)

except Exception as exc:
    print(f"ERROR: {exc}", file=sys.stderr)
    sys.exit(1)

print("Applied rainwater recipe-toggle follow-up:")
for item in changed:
    print(f" - {item}")
